import re, sys
from pathlib import Path
roots = [Path('compiler/test/CodeGen/VC4Tile'), Path('compiler/test/Conversion/VC4TileToSSAVC4'), Path('compiler/test/Dialect/VC4Tile')]
files = sorted({p for root in roots for p in root.rglob('*.mlir') if 'Output' not in p.parts})
launch_allowed = {'compiler/test/Dialect/VC4Tile/formal-args-invalid.mlir', 'compiler/test/Conversion/VC4TileToSSAVC4/metadata-copy.mlir', 'compiler/test/Conversion/VC4TileToSSAVC4/minimal-kernel.ssavc4.mlir'}
uniform_allowed = {'compiler/test/Dialect/VC4Tile/formal-args-invalid.mlir'}
identity_files = {'compiler/test/Conversion/VC4TileToSSAVC4/ids-arith-masks.mlir', 'compiler/test/Conversion/VC4TileToSSAVC4/uniform-control-flow.mlir', 'compiler/test/Conversion/VC4TileToSSAVC4/formal-args-lowering.mlir', 'compiler/test/CodeGen/VC4Tile/Emit/ids-arith-masks-vc4tile.mlir', 'compiler/test/CodeGen/VC4Tile/Emit/program-id-writeback-vc4tile.mlir', 'compiler/test/CodeGen/VC4Tile/Hardware/Run/program_id_writeback_vc4tile/input.mlir'}
fail = []
for p in files:
    rel = p.as_posix()
    text = p.read_text(encoding='utf-8')
    code = '\n'.join(line for line in text.splitlines() if not line.lstrip().startswith('//'))
    if re.search(r'vc4tile\.program_id[^\n]*uniform_index|program_id\s*\{uniform_index', code) and rel not in uniform_allowed:
        fail.append(f'{rel}: program_id carries uniform_index')
    if re.search(r'\blaunch_abi\s*=', code) and rel not in launch_allowed:
        fail.append(f'{rel}: manual launch_abi in active VC4Tile source')
    if re.search(r'%(base|out|ptr|buffer|n|x|y|alpha)[A-Za-z0-9_]*\s*=\s*vc4tile\.program_id', code) and rel not in identity_files:
        fail.append(f'{rel}: program_id assigned to user/base-like name')
    if re.search(r'vc4tile\.masked_(load|store)_global\s+%[A-Za-z0-9_]*(base|out|ptr|program)\b', code) and 'vc4tile.program_id' in code and rel not in identity_files:
        fail.append(f'{rel}: program_id-bearing file stores/loads through base-like operand outside identity allowlist')
for p in sorted(Path('compiler/test/CodeGen/VC4Tile/Hardware/Run').glob('*/input.vc4tile.mlir')):
    text = p.read_text(encoding='utf-8')
    if 'vc4tile.kernel' in text or not re.search(r'^\s*// RUN: true\s*$', text, flags=re.M):
        fail.append(f'{p.as_posix()}: stale input.vc4tile.mlir must be a non-generating compatibility stub')
if fail:
    print('\n'.join(fail))
    sys.exit(1)
print(f'vc4tile-abi-cleanup-ok files={len(files)}')
